def fit(a, b):
    from scipy.linalg import lstsq
    return lstsq(a, b)[0]

def estimate(u, v, fn, p0, bounds):
    from scipy.optimize import least_squares

    def resid(p):
        d = fn(u, p)
        return (d @ fit(d, v) - v).ravel()
    p = least_squares(resid, p0, bounds=bounds, gtol=1e-12, ftol=1e-12, xtol=1e-12).x
    a = fn(u, p)
    c = fit(a, v)
    h = (np.linalg.svd(a, full_matrices=False)[0] ** 2).sum(1)
    rms = np.sqrt(np.mean(resid(p) ** 2))
    loo = np.mean(abs((a @ c - v) / (1 - h[:, None])))
    return (rms, loo, p, lambda z: fn(z, p) @ c)

def pol(x, d):
    from itertools import combinations_with_replacement
    return np.column_stack([np.prod(x[:, i], axis=1) for n in range(d + 1) for i in combinations_with_replacement(range(x.shape[1]), n)])
